if(!args?.tasks?.length||args.tasks.length>3)throw Error('At most three bounded visual tasks');
await phase('Inspect turned body construction and complete alternating strides');
const schema={type:'object',properties:{verdict:{type:'string',enum:['PASS','GAP','UNVERIFIED']},imagesViewed:{type:'array',maxItems:40,items:{type:'string'}},coverage:{type:'array',maxItems:40,items:{type:'object',properties:{id:{type:'string'},verdict:{type:'string',enum:['PASS','GAP','UNVERIFIED']},observation:{type:'string'}},required:['id','verdict','observation'],additionalProperties:false}},findings:{type:'array',maxItems:12,items:{type:'string'}},limitations:{type:'array',maxItems:6,items:{type:'string'}}},required:['verdict','imagesViewed','coverage','findings','limitations'],additionalProperties:false};
const rows=await parallel(args.tasks.map(task=>()=>agent('Independently inspect the ACTUAL PNG images in this frozen task: '+JSON.stringify(task)+'. Verify the assigned file hashes and use image-viewing tools on EVERY assigned image; no prior verdicts. For read-only hash commands prefer Python hashlib, or explicitly disable PowerShell profiles with -NoProfile / exec login:false. Do not load interactive shell profiles. These are intentionally simple bare anatomical mannequin starters, not finished people. Each static sheet has four facings at native person scale. Each motion sheet has eight unique frames in reading order, top row 0-3 then bottom row 4-7. Judge coherent chosen proportions, recognizable front/back/three-quarter planes, rear skull without front face marks, proper shoulder/hip attachment, continuous limb mass, anatomical knee/elbow direction, near/far overlap, foot/calf alignment and toe direction. Moving poses use shallow top-down projection: different ground-depth feet have different screen y; projected bones shorten correctly with foreshortening. The original E/W static source drawings are deliberately retained, so their slight profile style difference is not itself a failure. Human is about seven heads; compact RPG is deliberately squat and large-headed. Motion: compare BOTH half-strides, one knee recovering forward while the other supports, opposing arms, planted versus flight phases, ankle orientation and final-to-first pose adjacency. Do not infer real timing, rendered game behavior or a seamless live loop from a sheet; root separately tests actual browser playback. A hovering limb is appropriate during run flight. Return one coverage row per supplied image, exact id. Concrete visible defects need exact model/view/action/frame. UNVERIFIED for images you cannot actually see. No edits, installations, services, browser launches, research, publishing, workflow controls, delegation or authoring skills. Ordinary read/image tools only.',{id:task.id,label:task.label,maxAttempts:1,timeoutMs:null,permissions:{sandbox:'read-only',networkAccess:false,approvalPolicy:'never'},schema})));
await phase('Return exact visual coverage and remaining gaps for root acceptance');
return {tasks:args.tasks.map((t,i)=>({id:t.id,result:rows[i],missing:rows[i]===null})),rootAcceptanceRequired:true,ownerAcceptanceNotInferred:true};
